  "checklist": [
    {
      "id": "macro_dag_no_cycle_no_task",
      "description": "macro result が feature/architecture/機能間 depends_on だけを持ち循環と phase-task 混入が0件である",
      "status": "pass",
      "evidence": "Explore Task and final audit agree on architecture 1 (arch-webapp-001) + feature 4 (feat-user-auth-001, feat-dashboard-001, feat-notification-001, feat-admin-report-001) + task 0. dashboard/notification/admin-report each depend on user-auth; DAG is acyclic and max inter-feature depends_on is 1 <= 3."
    },
    {
      "id": "draft_publication_zero",
      "description": "draft/unconfirmed/evaluation非pass/readiness非complete の tracker publication が0件である",
      "status": "pass",
      "evidence": "Three draft features remain excluded for reason draft_gate; only confirmed/pass/readiness-complete feat-user-auth-001 is a publication candidate."
    },
    {
      "id": "ready_package_p01_p13",
      "description": "各 ready feature package が P01..P13 exact 13、共通 parent/package、13-node DAG を満たす",
      "status": "not_applicable",
      "evidence": "Macro-only scenario; system-dev-planner was not invoked, so P01..P13 is not applicable."
    },
    {
      "id": "c02_all_or_none",
      "description": "C02 local commit が all-or-none で、自動/手動経路の重複 node が0件である",
      "status": "pass",
      "evidence": "All five nodes were registered through upsert-node.py, the promoted digest matched the final persisted node, and all five resends returned operation=noop/write_count=0."
    },
    {
      "id": "binding_authority",
      "description": "beads/github/none の各 task が単一 projection authority と linkage を持つ",
      "status": "pass",
      "evidence": "Explore Task and persisted graph agree that all nodes use tracker_binding=beads, beads_linkage=null and github_publication.mode=local_only. github binding is unreachable for macro-only local_only nodes because the schema requires issue or issue_and_projects."
    },
    {
      "id": "dryrun_write_zero",
      "description": "--dry-run の local/Beads/GitHub/Projects write count が0である",
      "status": "not_applicable",
      "evidence": "This is an apply-mode OUT1 run, not a dry-run."
    },
    {
      "id": "goal_seek_fork",
      "description": "goal_seek.fork=subagent を Explore の分離 context で実行し結果を回収した",
      "status": "pass",
      "evidence": "subagent_type=Explore completed and returned architecture 1 + feature 4 + task 0, the three dependency edges, acyclic/max-dependency=1 checks, tracker_binding=beads constraints, github macro-only schema risk, and P01..P13 non-applicability. Nested Task tools were Read/Grep/Glob only; Bash and file generation/modification counts were both 0."
    }
  ],
  "overall": "pass"
}

