def _assert_c14_macro_contract(node: dict[str, Any], root: Path) -> None:
    """feature は C14 macro contract 由来だけを受理する (通常 artifact routing では作らせない)。

    SKILL.md OUT1 / MM 契約: 「feature は C14 の macro contract から受け取り、通常 artifact
    routing で新規生成しない」。この gate が無い間、lineage が manual/全 null の feature が
    通常 add で登録され features/ に実ファイルが作られていた (2026-07-21 live-trial r13)。

    fail-closed: 判定に必要な情報が欠けている場合は必ず ContractError を送出する。
    """
    lineage = node.get("source_lineage")
    if not isinstance(lineage, dict):
        raise ContractError(
            "feature requires source_lineage proving C14 macro contract provenance"
        )

    def source_digest_matches() -> bool:
        """source_path の実ファイル内容が source_digest と一致するかを実測する。"""
        raw = lineage.get("source_path")
        expected = lineage.get("source_digest")
        if not isinstance(raw, str) or not raw or not isinstance(expected, str) or not expected:
            return False
        try:
            source = contained(root / raw, root, must_exist=True)
        except (ContractError, OSError):
            return False
        return _sha256(source.read_bytes()) == expected

    origin_kind = lineage.get("origin_kind")
    if origin_kind not in MACRO_FEATURE_ORIGIN_KINDS:
        raise ContractError(
            "feature must come from the C14 macro contract: "
            f"source_lineage.origin_kind {origin_kind!r} is not one of "
            f"{sorted(MACRO_FEATURE_ORIGIN_KINDS)}"
        )
    source_plugin = lineage.get("source_plugin")
    if not isinstance(source_plugin, str) or not source_plugin.strip():
        raise ContractError(
            "feature from the C14 macro contract requires source_lineage.source_plugin"
        )
    if not source_digest_matches():
        raise ContractError(
            "feature from the C14 macro contract requires source_lineage.source_path to be a "
            "contained repository file whose sha256 equals source_lineage.source_digest"
        )


def _request_node(
    payload: dict[str, Any], existing: dict[str, Any] | None,
) -> tuple[dict[str, Any], bool]:
    if "node" in payload and "patch" in payload:
        raise ContractError("input must contain either node or patch, not both")
    if "node" in payload:
        raw = payload["node"]
        if not isinstance(raw, dict):
            raise ContractError("input node must be an object")
        node = copy.deepcopy(raw)
        explicit_updated_at = "updated_at" in raw
    elif "patch" in payload:
        if existing is None:
            raise ContractError("patch requires an existing graph node")

    known = _string_assignments(command)
    if not known:
        return command
    return _IDENTIFIER.sub(
        lambda hit: f"'{known[hit.group(0)]}'" if hit.group(0) in known else hit.group(0),
        command,
    )


def payload() -> dict:
    try:
        value = json.load(sys.stdin)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def command_of(value: dict) -> str:
    tool_input = value.get("tool_input") or {}
    return str(tool_input.get("command") or "") if isinstance(tool_input, dict) else ""


def written_paths_of(value: dict) -> list[str]:
    """Write/Edit 系ツールが書込む対象 path を返す (Bash 以外の C02 迂回経路)。"""
    if str(value.get("tool_name") or "") not in FILE_WRITING_TOOLS:
        return []
    tool_input = value.get("tool_input") or {}
    if not isinstance(tool_input, dict):
        return []
    return [
        str(tool_input[key])
        for key in ("file_path", "notebook_path")
        if isinstance(tool_input.get(key), str) and tool_input[key]
    ]


def _open_mode_is_write(mode: str) -> bool:
    """open() の mode 文字列が書込みを含むか (w/a/x、または ``+`` を含む)。"""
    mode = mode.lower()
    if not mode:
        return False
    # Python の open() は ``rb+`` だけでなく ``br+`` / ``+rb``、``wb`` だけでなく
    # ``bw`` も受理する。先頭文字だけを見ると同じ有効 mode の並び替えで guard を迂回
    # できるため、書込み能力を与える文字が mode 内のどこにあるかで判定する。
    return bool(set(mode) & {"w", "a", "x"}) or "+" in mode


def _literal_interpreter_write(command: str) -> bool:
    """字面に現れる path/mode だけで interpreter 経由の graph authority 書込みを判定する。

    保証範囲 (HarnessHub-lp36): 字面パターンに一致する次の書込み API のみを検出する。
    ``open(path, mode)`` (mode が w/a/x/r+ 系)・``Path.write_text``・``Path.write_bytes``・
    ``Path.touch``・``Path.unlink``・``Path.rmdir``・``Path.open(w/a/x)``・``shutil.copy*``・
    ``shutil.move``・``os.replace``・``os.rename``・``json.dump``。これらは静的正規表現一致で
    あり、変数を経由した path/mode (例: ``open(p, m)``)・エイリアス import
    (``from shutil import copy as cp``)・``exec``/``eval`` 経由の間接呼出し・``os.open`` の
    低レベル fd 系は検出できない。これらは C02 atomic writer (``upsert-node.py`` /
    ``build-graph-store.py`` / ``build-repo-config.py``) の使用を運用規約として要求すること
    でしか閉じられない。
    """
    for match in INTERPRETER_WRITE.finditer(command):
        path = match.group("path") or match.group("path2") or ""
        if not GRAPH_AUTHORITY_PATH.search(path):
            continue
        mode = match.group("mode") or match.group("mode2") or ""
        if _open_mode_is_write(mode):
            return True
    # ``Path.write_text`` / ``shutil.copy`` 等は path を ``open(...)`` の第 1 引数として渡さない
    # ため上の枝では検出できない。API 呼出しと graph authority の文字列が同一コマンド内に
    # 共起するかだけを見る粗い判定にとどめ (path/mode の対応関係までは解析しない)、
    # ``Path.read_text`` のような読取専用呼出しは対象外のまま残す。
    if PATHLIB_MUTATION.search(command) and GRAPH_AUTHORITY_LITERAL.search(command):
        return True
    return False


